    ("Smoky Pinto Beans", 35, "Tex-Mex", "450 g|dried pinto beans, soaked overnight; 1|onion, chopped; 1 tbsp|chipotle peppers in adobo, chopped; 1 tsp|cumin", "Soften the onion in a little oil, then stir in the chipotle and cumin"),
    ("Cuban Black Beans", 30, "Cuban", "450 g|dried black beans, soaked overnight; 1|green bell pepper, chopped; 1|onion, chopped; 4|garlic cloves; 1 tsp|cumin; 2 tbsp|red wine vinegar", "Soften the onion, pepper and garlic in a little oil"),
    ("Chickpeas from Dry", 40, "International", "450 g|dried chickpeas, soaked overnight; 1|bay leaf; 1 tsp|salt", ""),
    ("Kidney Bean Rajma", 35, "Indian", "300 g|dried kidney beans, soaked overnight; 1|onion, chopped; 2 tbsp|ginger garlic paste; 400 g|chopped tomatoes; 2 tsp|garam masala", "Fry the onion until golden, then the paste and garam masala"),
    ("Butter Beans with Tomato and Dill", 25, "Greek", "450 g|dried butter beans, soaked overnight; 1|onion, chopped; 400 g|chopped tomatoes; 1 handful|dill; 4 tbsp|olive oil", "Soften the onion in the oil"),
