    ("Agua de Pepino con Limón y Chía", "Mexican", 10, 0, 4, "2|cucumbers; 3|limes; 3 tbsp|sugar; 1 tbsp|chia seeds; 1 l|water, cold", "Blend the cucumbers with the lime juice, sugar and half the water and strain / Stir in the rest of the water and the chia and leave 10 minutes before serving over ice"),
    ("Sweet Tea (Southern Style)", "Southern US", 5, 10, 8, "6|black tea bags; 2 l|water; 150 g|sugar; 0.25 tsp|baking soda", "Steep the tea in 1 litre just-boiled water with the soda for 10 minutes / Remove the bags and stir in the sugar / Add 1 litre cold water and chill"),
    ("Moroccan Mint Tea", "Moroccan", 2, 5, 4, "2 tsp|gunpowder green tea; 1 large handful|mint; 3 tbsp|sugar; 1 l|water, boiling", "Rinse the tea with a splash of boiling water and discard / Add the mint, sugar and the rest of the water and steep 4 minutes / Pour from a height into small glasses"),
    ("Korean Sikhye-Style Rice Drink", "Korean", 10, 15, 6, "300 g|rice, cooked; 1.5 l|water; 100 g|sugar; 3 cm|ginger, sliced", "Simmer the rice, ginger and water 10 minutes / Stir in the sugar, cool and chill / Serve cold with a few rice grains in each glass"),
    ("Brazilian Lemonade (Limonada Suíça)", "Brazilian", 5, 0, 4, "4|limes, quartered; 100 g|sugar; 4 tbsp|sweetened condensed milk; 1 l|water, cold", "Blend the limes, sugar and water for only 10 seconds / Strain at once, whisk in the condensed milk and serve over ice"),
